B.abm=new A.kO("\u062a\u0628\u062a\u0633\u0645 \u0627\u0644\u062c\u062f\u0629 \u0648\u062a\u0642\u0648\u0644: \u0647\u064a\u0627 \u0646\u0632\u0631\u0639\u0647\u0627 \u0645\u0639\u064b\u0627! \u0645\u0627\u0630\u0627 \u064a\u062d\u062a\u0627\u062c\u0648\u0646 \u0623\u0648\u0644\u064b\u0627\u061f",'Grandma smiles and says, "Let us plant it together!" What do they need first?',B.bn5)
